{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "AZD0837, the closest analogue and a thrombin-inhibitor prodrug with a benzamidine-like hydroxyamidine/methoxyamidine motif, has absolute oral bioavailability of 22–52% in humans, directly supporting F ≥20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Inogatran, a related peptidic thrombin inhibitor without the ester/hydroxyamidine prodrug groups, has oral bioavailability <5%; this low-F direction is contradicted by the query's prodrug design and lower transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C24"],
      "claim": "Perindopril, an ethyl ester prodrug ACE inhibitor with a peptide-like backbone, has absolute oral bioavailability about 75%, supporting the absorption-enhancing effect of the ethyl ester motif in the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Moexipril, another ethyl ester prodrug ACE inhibitor, has oral bioavailability of 22%, at the threshold and therefore supportive of F ≥20% for a similar ester prodrug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Oseltamivir, an ethyl ester prodrug, has absolute oral bioavailability of 79%, providing broad evidence that ester prodrugs of polar carboxylate-containing drugs can achieve high oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Tolperisone has very low oral bioavailability in humans, but its structure lacks the peptidic/prodrug features of the query and has low similarity, so it is weak contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a double prodrug (ethyl ester plus hydroxyamidine) in the oral thrombin-inhibitor class. The closest analogue AZD0837 has F 22–55% in humans, and multiple ester prodrugs (perindopril, moexipril, oseltamivir) show F ≥22%, supporting F ≥20%. Low-F analogues are non-prodrug or structurally distant and carry less weight.",
  "evidence_gaps": [
    "No direct absolute bioavailability record for the exact query molecule in the supplied evidence.",
    "The threshold is close to the lower end of the supportive range; formulation and dose effects are not captured.",
    "No human pharmacokinetic record for a compound with both ethyl ester and hydroxyamidine prodrug groups in the evidence set."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

